			signals := []string{"sparse-region"}
			if len(pathCounts) > 0 {
				signals = append(signals, "path")
			}
			out = append(out, searchCandidate{
				result: SearchResult{
					FilePath:         filePath,
					StartLine:        start,
					EndLine:          end,
					FocusLine:        focus,
					SnippetStartLine: snippetStart,
					SnippetEndLine:   snippetEnd,
					Language:         language,
					Signals:          signals,
					Snippet:          "",
				},
				termCounts: counts,
				docLength:  length,
			})
		}
		if end == len(lines) {
			break
		}
	}
	return out, documentCount, documentLength
}

