			}
			run = append(run, index)
			runEnd = end
		}
		flush()
	}
	sort.SliceStable(runs, func(a, b int) bool {
		return bestSearchSpanRank(results, runs[a]) < bestSearchSpanRank(results, runs[b])
	})
	return runs
